import {diagonalRoad} from './diagonal-roads.js';
import {BIOME_TERRAIN} from './biome-gameplay-data.js';
export function tilePreview(kind){if(BIOME_TERRAIN[kind])return '../assets/environment/biome-foliage/ground-tiles/'+BIOME_TERRAIN[kind]+'/ground-0.png';const info=diagonalRoad(kind),palette={'ground-grass':'#668350','ground-dirt':'#a98c64','ground-gravel':'#929080','ground-concrete':'#b4b2a8','ground-asphalt':'#505554','ground-tiles':'#b5a090','ground-wood-planks':'#987449','water':'#4b93a5','bridge':'#9d947b','floor':'#b8b6a5','woodland':'#395d3b'},color=palette[kind]||'#7e9564';let shape='';if(kind==='ground-wood-planks')shape='<path d="M0 0H64M0 16H64M0 32H64M0 48H64M1 0V16M32 16V32M1 32V48M32 48V64" stroke="#493423" stroke-width="2"/><path d="M0 3H64M0 19H64M0 35H64M0 51H64M3 9Q22 5 45 10T64 8M3 25Q24 29 62 24M2 41Q32 37 62 43M3 57Q32 60 62 56" fill="none" stroke="#d1ad76" opacity=".6"/>';if(info){const points={nw:'0,0 64,0 0,64',ne:'0,0 64,0 64,64',se:'64,0 64,64 0,64',sw:'0,0 0,64 64,64'}[info.corner];shape=`<polygon points="${points}" fill="#505554"/>`;if(info.border)shape+=`<path d="${['nw','se'].includes(info.corner)?'M0 64L64 0':'M0 0L64 64'}" stroke="#c6c3b8" stroke-width="4"/>`;}
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" fill="${info?.grass==='concrete'?'#b4b2a8':info?.grass?.includes('sand')?'#cfb985':color}"/>${shape}<path d="M16 0V64M32 0V64M48 0V64M0 16H64M0 32H64M0 48H64" stroke="#172c29" opacity=".12" fill="none"/><path d="M3 4h4m15 5h3m21 2h7m-41 22h5m17 11h5m14 9h4" stroke="#fff" opacity=".18"/></svg>`;return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);}
